import { useEffect, useState } from "react";
import QuestionCard from "../components/QuestionCard";
import Timer from "../components/Timer";
import Confetti from "react-confetti";

const QUESTION_API = "https://harini05.app.n8n.cloud/webhook/generate-questions";
const ANSWER_API = "https://harini05.app.n8n.cloud/webhook/submit-answer";

function Practice() {
  const [question, setQuestion] = useState(null);
  const [selected, setSelected] = useState("");
  const [result, setResult] = useState("");
  const [loading, setLoading] = useState(false);
  const [time, setTime] = useState(15);
  const [started, setStarted] = useState(false);

  const parseQuestion = (rawText) => {
    let cleanQuestion = rawText;
    let options = [];
    let answer = "A";
    let explanation = "Generated explanation";

    if (rawText.includes("A)")) {
      cleanQuestion = rawText.split("A)")[0].trim();

      const a = rawText.match(/A\)(.*?)(B\)|$)/s)?.[1]?.trim() || "";
      const b = rawText.match(/B\)(.*?)(C\)|$)/s)?.[1]?.trim() || "";
      const c = rawText.match(/C\)(.*?)(D\)|$)/s)?.[1]?.trim() || "";
      const d = rawText.match(/D\)(.*?)(Correct Answer:|Explanation:|$)/s)?.[1]?.trim() || "";

      options = [a, b, c, d];
    }

    else if (rawText.includes("Options:")) {
      cleanQuestion = rawText.split("Options:")[0].trim();

      const optionText = rawText.split("Options:")[1]?.split("Correct Answer")[0] || "";

      const matches = optionText.match(/\d+\.\s*[^0-9]+/g);

      if (matches) {
        options = matches.map((x) => x.replace(/\d+\./, "").trim());
      }
    }

    answer = rawText.match(/Correct Answer:\s*([A-D]|\d+)/i)?.[1] || "A";

    explanation = rawText.split("Explanation:")[1]?.trim() || "Generated explanation";

    while (options.length < 4) {
      options.push("");
    }

    return {
      question: cleanQuestion,
      options,
      answer,
      explanation,
    };
  };

  const fetchQuestion = async () => {
    setLoading(true);

    try {
      const res = await fetch(QUESTION_API);
      const raw = await res.json();

      const data = Array.isArray(raw) ? raw[0] : raw;

      const parsed = parseQuestion(data.question);

      setQuestion(parsed);
      setSelected("");
      setResult("");
      setTime(15);
    } catch (err) {
      console.log(err);
    }

    setLoading(false);
  };

  const handleStart = async () => {
    setStarted(true);
    await fetchQuestion();
  };

  const handleSubmit = async () => {
    if (selected === "") return;

    setLoading(true);

    try {
      const res = await fetch(ANSWER_API, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          studentId: "STU001",
          questionId: "Q001",
          selectedAnswer: ["A", "B", "C", "D"][selected],
        }),
      });

      const data = await res.json();

      if (data.correct) {
        setResult(`✅ Correct | Score ${data.score}`);
      } else {
        setResult(`❌ Wrong | Correct Answer ${data.correctAnswer}`);
      }
    } catch (err) {
      console.log(err);
    }

    setLoading(false);
  };

  useEffect(() => {
    if (time === 0 && !result) {
      setResult("⏰ Time Up");
    }
  }, [time, result]);

  if (!started) {
    return (
      <div className="p-8">
        <button
          onClick={handleStart}
          className="bg-blue-500 text-white px-6 py-3 rounded"
        >
          Start Practice
        </button>
      </div>
    );
  }

  if (!question) {
    return <div className="p-8">Loading...</div>;
  }

  return (
    <div className="p-8">
      {result.includes("Correct") && <Confetti />}

      <Timer time={time} setTime={setTime} />

      <QuestionCard
        question={question.question}
        options={question.options}
        selected={selected}
        setSelected={setSelected}
      />

      <button
        onClick={handleSubmit}
        className="bg-green-500 text-white px-5 py-2 rounded mt-4"
      >
        Submit
      </button>

      {result && (
        <div className="mt-4">
          <p>{result}</p>
          <p className="mt-2">Explanation: {question.explanation}</p>

          <button
            onClick={fetchQuestion}
            className="bg-purple-500 text-white px-5 py-2 rounded mt-4"
          >
            Next Question
          </button>
        </div>
      )}
    </div>
  );
}

export default Practice;
